create table if not exists public.mapping_import_bloom_chunks (
  import_batch_id uuid not null references public.mapping_import_batches(import_batch_id) on delete cascade,
  chunk_no integer not null,
  base64_data text not null,
  primary key (import_batch_id, chunk_no)
);

create table if not exists public.mapping_import_bloom_filters (
  import_batch_id uuid primary key references public.mapping_import_batches(import_batch_id) on delete cascade,
  m_bits integer not null,
  k_hashes integer not null,
  filter_data bytea not null,
  created_at timestamptz not null default now()
);

create or replace function public.expand_mapping_import_bloom(p_batch_id uuid, p_m_bits integer, p_k_hashes integer)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  combined text;
  decoded bytea;
begin
  select string_agg(base64_data, '' order by chunk_no)
    into combined
  from public.mapping_import_bloom_chunks
  where import_batch_id = p_batch_id;

  if combined is null then
    raise exception 'no bloom chunks for batch %', p_batch_id;
  end if;

  decoded := decode(combined, 'base64');
  if octet_length(decoded) * 8 < p_m_bits then
    raise exception 'bloom payload too short for batch %: % bytes for % bits', p_batch_id, octet_length(decoded), p_m_bits;
  end if;

  insert into public.mapping_import_bloom_filters(import_batch_id, m_bits, k_hashes, filter_data)
  values (p_batch_id, p_m_bits, p_k_hashes, decoded)
  on conflict (import_batch_id) do update
    set m_bits = excluded.m_bits,
        k_hashes = excluded.k_hashes,
        filter_data = excluded.filter_data,
        created_at = now();

  return octet_length(decoded);
end;
$$;

create or replace function public.mapping_bloom_contains(p_batch_id uuid, p_key text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  f public.mapping_import_bloom_filters%rowtype;
  digest_hex text;
  h1 bigint;
  h2 bigint;
  a bigint;
  b bigint;
  i integer;
  pos bigint;
  byte_index integer;
  bit_index integer;
  byte_value integer;
begin
  select * into f from public.mapping_import_bloom_filters where import_batch_id = p_batch_id;
  if not found then return false; end if;

  digest_hex := md5(coalesce(p_key, ''));
  h1 := ('x' || substr(digest_hex, 1, 15))::bit(60)::bigint;
  h2 := ('x' || substr(digest_hex, 17, 15))::bit(60)::bigint;
  if h2 = 0 then h2 := 1; end if;
  a := mod(h1, f.m_bits);
  b := mod(h2, f.m_bits);

  for i in 0..f.k_hashes - 1 loop
    pos := mod(a + i::bigint * b, f.m_bits);
    byte_index := (pos / 8)::integer;
    bit_index := (pos % 8)::integer;
    byte_value := get_byte(f.filter_data, byte_index);
    if (byte_value & (1 << bit_index)) = 0 then
      return false;
    end if;
  end loop;
  return true;
end;
$$;

revoke all on function public.expand_mapping_import_bloom(uuid,integer,integer) from public, anon, authenticated;
revoke all on function public.mapping_bloom_contains(uuid,text) from public, anon, authenticated;

alter table public.mapping_import_bloom_chunks enable row level security;
alter table public.mapping_import_bloom_filters enable row level security;
